    std::uint8_t *aCrystalLaneD = pWorkSpace->mCrystalLaneD;

    std::uint8_t *aMuLaneA = pWorkSpace->mCelestialLaneA;
    std::uint8_t *aLelLaneA = pWorkSpace->mAlchemyLaneA;
    std::uint8_t *aGozLaneA = pWorkSpace->mAuguryLaneA;
