    // Mu A[4]: aCrystalLaneD[1] + aCrystalLaneC[24].
    KEY_FOLD_BLOCK(aCrystalLaneD, 1U, 138U, aCrystalLaneC, 24U, 186U, aMuLaneA, 4U);

    // Mu A[5]: aEarthLaneC[32] + aEarthLaneB[15].
    KEY_FOLD_BLOCK(aEarthLaneC, 32U, 472U, aEarthLaneB, 15U, 210U, aMuLaneA, 5U);

    // Mu A[6]: aCrystalLaneB[17] + aEarthLaneD[13].
    KEY_FOLD_BLOCK(aCrystalLaneB, 17U, 158U, aEarthLaneD, 13U, 334U, aMuLaneA, 6U);

    // Mu A[7]: aEarthLaneA[34] + aCrystalLaneD[63].
