    // Mu B[0]: aEarthLaneC[20] + aEarthLaneD[19].
    KEY_FOLD_BLOCK(aEarthLaneC, 20U, 346U, aEarthLaneD, 19U, 338U, aMuLaneB, 0U);

    // Mu B[1]: aCrystalLaneB[53] + aCrystalLaneC[38].
    KEY_FOLD_BLOCK(aCrystalLaneB, 53U, 19U, aCrystalLaneC, 38U, 441U, aMuLaneB, 1U);

    // Mu B[2]: aCrystalLaneD[41] + aCrystalLaneC[20].
    KEY_FOLD_BLOCK(aCrystalLaneD, 41U, 52U, aCrystalLaneC, 20U, 477U, aMuLaneB, 2U);

    // Mu B[3]: aCrystalLaneA[52] + aCrystalLaneB[39].
